definition.script:
pipeline {
    agent any
    parameters {
        string(name: 'BRANCH',  defaultValue: 'tmp')
        string(name: 'TEST',    defaultValue: 'm115/t1')
        string(name: 'WORKERS', defaultValue: '4')
        string(name: 'FILTER',  defaultValue: '')
        string(name: 'EXEMODE', defaultValue: 'dynamic')
    }

    stages {
        stage('Setup users') {
            steps {
                build job: 'The job - dev',
                      parameters: [
                          string(name: 'BRANCH',  value: "${params.BRANCH}"),
                          string(name: 'TEST',    value: "m115/t2"),
                          string(name: 'WORKERS', value: "${params.WORKERS}"),
                          string(name: 'FILTER',  value: "${params.FILTER}"),
                          string(name: 'NUMBER',  value: "${env.BUILD_NUMBER}"),
                          string(name: 'EXEMODE', value: "${params.EXEMODE}")
                      ]
            }
        }

        stage('Run Smoke tests') {
            steps {
                catchError(buildResult: 'SUCCESS', stageResult: 'SUCCESS') {
                    build job: 'The job - dev',
                          parameters: [
                              string(name: 'BRANCH',  value: "${params.BRANCH}"),
                              string(name: 'TEST',    value: "m82/t3"),
                              string(name: 'WORKERS', value: "${params.WORKERS}"),
                              string(name: 'FILTER',  value: "${params.FILTER}"),
                              string(name: 'NUMBER',  value: "${env.BUILD_NUMBER}"),
                              string(name: 'EXEMODE', value: "${params.EXEMODE}")
                          ]
                }
            }
        }

        stage('Run phase 1 tests') {
            steps {
                catchError(buildResult: 'SUCCESS', stageResult: 'SUCCESS') {
                    build job: 'The job - dev',
                          parameters: [
                              string(name: 'BRANCH',  value: "${params.BRANCH}"),
                              string(name: 'TEST',    value: "m41/t1"),
                              string(name: 'WORKERS', value: "${params.WORKERS}"),
                              string(name: 'FILTER',  value: "modeltests"),
                              string(name: 'NUMBER',  value: "${env.BUILD_NUMBER}"),
                              string(name: 'EXEMODE', value: "${params.EXEMODE}")
                          ]
                }
            }
        }

        stage('Run form fill tests') {
            steps {
                catchError(buildResult: 'SUCCESS', stageResult: 'SUCCESS') {
                    build job: 'The job - dev',
                          parameters: [
                              string(name: 'BRANCH',  value: "${params.BRANCH}"),
                              string(name: 'TEST',    value: "m41/t1"),
                              string(name: 'WORKERS', value: "${params.WORKERS}"),
                              string(name: 'FILTER',  value: "formtests"),
                              string(name: 'NUMBER',  value: "${env.BUILD_NUMBER}"),
                              string(name: 'EXEMODE', value: "${params.EXEMODE}")
                          ]
                }
            }
        }

        stage('Not model-based') {
            steps {
                catchError(buildResult: 'SUCCESS', stageResult: 'SUCCESS') {
                    build job: 'The job - dev',
                          parameters: [
                              string(name: 'BRANCH',  value: "${params.BRANCH}"),
                              string(name: 'TEST',    value: "m82/t8"),
                              string(name: 'WORKERS', value: "1"),
                              string(name: 'FILTER',  value: ""),
                              string(name: 'NUMBER',  value: "${env.BUILD_NUMBER}"),
                              string(name: 'EXEMODE', value: "${params.EXEMODE}")
                          ]
                }
            }
        }

        stage('Phase 3') {
            steps {
                catchError(buildResult: 'SUCCESS', stageResult: 'SUCCESS') {
                    build job: 'The job - dev',
                          parameters: [
                              string(name: 'BRANCH',  value: "${params.BRANCH}"),
                              string(name: 'TEST',    value: "m82/t25"),
                              string(name: 'WORKERS', value: "${params.WORKERS}"),
                              string(name: 'FILTER',  value: ""),
                              string(name: 'NUMBER',  value: "${env.BUILD_NUMBER}"),
                              string(name: 'EXEMODE', value: "${params.EXEMODE}")
                          ]
                }
            }
        }

        stage('Claude') {
            steps {
                catchError(buildResult: 'SUCCESS', stageResult: 'SUCCESS') {
                    build job: 'The job - dev',
                          parameters: [
                              string(name: 'BRANCH',  value: "${params.BRANCH}"),
                              string(name: 'TEST',    value: "m82/t28"),
                              string(name: 'WORKERS', value: "1"),
                              string(name: 'FILTER',  value: ""),
                              string(name: 'NUMBER',  value: "${env.BUILD_NUMBER}"),
                              string(name: 'EXEMODE', value: "${params.EXEMODE}")
                          ]
                }
            }
        }
    }

    // --- Always run this cleanup block at the very end ---
    post {
        always {
            echo "Running final cleanup..."
            sh '''
                echo "Number of Chrome processes before cleanup"
                sudo ps -ef | grep chrome | wc -l
                sudo pkill chrome || true
                echo "Number of Chrome processes after cleanup"
                sudo ps -ef | grep chrome | wc -l
                echo "Cleanup complete."
            '''
        }
    }
}
